function getBlogPostBySlug(slug) {
    return exports.blogPosts.find(function (post) { return post.slug === slug; });
}
function getBlogPostsByCategory(category) {
    return exports.blogPosts.filter(function (post) { return post.category === category; });
}
function getAllBlogCategories() {
    var categories = new Set(exports.blogPosts.map(function (post) { return post.category; }));
    return Array.from(categories).sort();
}
function getRelatedPosts(slug, limit) {
    if (limit === void 0) { limit = 3; }
    var currentPost = getBlogPostBySlug(slug);
    if (!currentPost)
        return [];
    return exports.blogPosts
        .filter(function (post) { return post.slug !== slug && post.category === currentPost.category; })
        .slice(0, limit);
}
